class Solution {
public:
    long long maximumImportance(int n, std::vector<std::vector<int>>& roads) {
        std::vector<long long> deg(n, 0);
        for (const auto& r : roads) {
            deg[r[0]]++;
            deg[r[1]]++;
        }
        std::sort(deg.begin(), deg.end());
        long long total = 0;
        for (int i = 0; i < n; ++i) {
            total += (i + 1) * deg[i];
        }
        return total;
    }
};

class Solution {
    public long maximumImportance(int n, int[][] roads) {
        long[] deg = new long[n];
        for (int[] r : roads) {
            deg[r[0]]++;
            deg[r[1]]++;
        }
        java.util.Arrays.sort(deg);
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += (long) (i + 1) * deg[i];
        }
        return total;
    }
}

var maximumImportance = function(n, roads) {
    const deg = new Float64Array(n);
